export async function resolveAsyncFallback(primary: { ok: boolean; value: unknown }, backup: unknown) {
  try{const value=await (primary.ok?Promise.resolve(primary.value):Promise.reject(new Error('Primary failed')));return {source:'primary',value};}
  catch{return {source:'fallback',value:await Promise.resolve(backup)};}
}
